import subprocess
import sys
from dataclasses import dataclass

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("file-manager")


@dataclass
class ScriptResult:
    exit_code: int
    stdout: str
    stderr: str
    timed_out: bool


@mcp.tool()
def run_folder_script(script_path: str, target_dir: str, timeout_seconds: int = 60) -> ScriptResult:
    try:
        proc = subprocess.run(
            [sys.executable, "-I", script_path, target_dir],
            capture_output=True,
            text=True,
            timeout=timeout_seconds,
        )
    except subprocess.TimeoutExpired as exc:
        return ScriptResult(-1, exc.stdout or "", exc.stderr or "", True)
    return ScriptResult(proc.returncode, proc.stdout[-4000:], proc.stderr[-4000:], False)

import os
from pathlib import Path

from agents import function_tool


def _apply_mode(target: Path, bits: int, recursive: bool) -> int:
    os.chmod(target, bits)
    count = 1
    if recursive and target.is_dir():
        for child in target.rglob("*"):
            os.chmod(child, bits)
            count += 1
    return count


@function_tool
def set_file_permissions(path: str, mode: str, recursive: bool = False) -> str:
    target = Path(path).expanduser().resolve()
    if not target.exists():
        return f"Path not found: {target}"
    bits = int(mode, 8)
    changed = _apply_mode(target, bits, recursive)
    return f"Set mode {mode} on {changed} item(s) under {target}"

import hashlib
from collections import defaultdict
from dataclasses import dataclass, field
from pathlib import Path


@dataclass
class DuplicateReport:
    groups: list = field(default_factory=list)
    wasted_bytes: int = 0
    files_scanned: int = 0


def _sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def find_duplicate_files(directory: str, min_size_bytes: int = 1) -> DuplicateReport:
    root = Path(directory).expanduser()
    by_size = defaultdict(list)
    report = DuplicateReport()
    for item in root.rglob("*"):
        if item.is_file() and not item.is_symlink():
            size = item.stat().st_size
            report.files_scanned += 1
            if size >= min_size_bytes:
                by_size[size].append(item)
    for size, paths in by_size.items():
        if len(paths) < 2:
            continue
        by_hash = defaultdict(list)
        for p in paths:
            by_hash[_sha256(p)].append(str(p))
        for digest, same in by_hash.items():
            if len(same) > 1:
                report.groups.append({"hash": digest, "size": size, "files": sorted(same)})
                report.wasted_bytes += size * (len(same) - 1)
    return report
